{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Guided intensives and frameworks for sustainable wellbeing." />
  <style>
    :root{--bg:#0f1724;--card:#0b1220;--muted:#9aa4b2;--accent:#8ee7c8;--glass:rgba(255,255,255,0.04);--maxw:1100px}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial;color:#e6eef6;background:linear-gradient(140deg,#071025 0%,#0b1b2a 60%);-webkit-font-smoothing:antialiased}
    header{max-width:var(--maxw);margin:28px auto;padding:18px 20px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#6bd3ff);display:flex;align-items:center;justify-content:center;color:#042;box-shadow:0 6px 18px rgba(8,12,20,.5)}
    nav a{color:#cfe9e0;text-decoration:none;margin:0 8px;font-weight:600}
    .ctas{display:flex;gap:10px;align-items:center}
    .primary{background:var(--accent);color:#012;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    main{max-width:var(--maxw);margin:12px auto;padding:22px}

    /* diagonal split hero */
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center;padding:28px;background:linear-gradient(180deg,transparent 0,transparent 65%),radial-gradient(800px 400px at 10% 20%,rgba(142,231,200,0.06),transparent 10%);border-radius:14px;position:relative;overflow:hidden}
    .hero:before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,0.02) 0%,transparent 40%);pointer-events:none}
    .hero .left{padding:16px}
    h1{margin:0;font-size:28px;color:#eafff6;line-height:1.02}
    p.lead{color:var(--muted);margin:12px 0 18px}
    .meta{display:flex;gap:12px;align-items:center}
    .pill{background:var(--glass);padding:6px 10px;border-radius:999px;color:#b9dacf;font-weight:600}
    .hero .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;color:#dff0ea}

    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:20px}
    .tier{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .tier h3{margin:0 0 8px;color:#e9fff6}
    .price{font-weight:800;font-size:20px;color:var(--accent)}
    .features{color:var(--muted);margin:12px 0 16px}
    .btn{display:inline-block;padding:10px 12px;background:#0f1724;border-radius:10px;color:var(--accent);text-decoration:none;font-weight:700}

    footer{max-width:var(--maxw);margin:40px auto 80px;padding:18px;color:var(--muted);text-align:center}

    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}

    /* modal */
    .modalWrap{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(2,6,12,0.6);z-index:60}
    .modal{background:#021220;color:#e8f7f2;width:94%;max-width:720px;border-radius:12px;padding:18px;box-shadow:0 18px 50px rgba(1,6,10,.6)}
    .modal header{display:flex;justify-content:space-between;align-items:center}
    .modal .exercise{margin-top:12px}
    .controls{display:flex;gap:8px;margin-top:12px}
    .muted{color:var(--muted);font-size:13px}
    .closeBtn{background:transparent;border:0;color:var(--muted);font-weight:700}

    /* small */
    @media (max-width:920px){
      .hero{grid-template-columns:1fr;}
      .tiers{grid-template-columns:1fr}
      header,main{padding:12px}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:800;color:#e6fff4">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Philosophy</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Paths</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
    <div class="ctas">
      <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button id="tryNow" title="Try exercise" style="background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:8px 10px;border-radius:10px">Try it now</button>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="left">
        <div class="pill">Six-week intensive alternative</div>
        <h1>Design a personal rhythm that supports your priorities</h1>
        <p class="lead">Practical frameworks to shape outcomes through tiny daily practices — habits, prompts, and review methods that move time into your favor.</p>
        <div class="meta">
          <div class="card">Outcome-focused, coach-led sessions + day-by-day templates</div>
          <div class="card">Remote friendly | Small cohort or private</div>
        </div>

        <div style="margin-top:18px">
          <a class="primary" href="book.html">Reserve a planning call</a>
          <a class="btn" href="#tiers" style="margin-left:10px">Compare options</a>
        </div>
      </div>
      <div>
        <div class="card" style="height:100%;display:flex;flex-direction:column;justify-content:center;align-items:flex-start">
          <strong style="color:#dfffe9">Investment framing</strong>
          <p class="muted" style="margin:8px 0 12px">We price by the scope of focus and level of support — choose a compact sprint or a bespoke engagement.</p>

          <div id="tiers" class="tiers reveal">
            <div class="tier">
              <h3>Foundations Sprint</h3>
              <div class="price">$1,100 — 4 weeks</div>
              <div class="features">Weekly session, daily check-in prompts, habit architecture template</div>
              <a class="btn" href="book.html#foundations">Select</a>
            </div>
            <div class="tier">
              <h3>Rhythm Build</h3>
              <div class="price">$2,400 — 8 weeks</div>
              <div class="features">Two deep sessions, custom tracking system, mid-series recalibration</div>
              <a class="btn" href="book.html#rhythm">Select</a>
            </div>
            <div class="tier">
              <h3>Steady Way</h3>
              <div class="price">$4,800 — 16 weeks</div>
              <div class="features">Bespoke plan, weekly accountability, systems for transfer into daily life</div>
              <a class="btn" href="book.html#steady">Select</a>
            </div>
          </div>

          <p class="muted" style="margin-top:12px">Need a tailored quote for teams or long-term support? Email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></p>
        </div>
      </div>
    </section>

    <section style="margin-top:28px" class="reveal">
      <h2 style="color:#e6fff6">How we frame investment</h2>
      <p class="muted">We orient pricing around clarity of outcome and coaching intensity: clarity first, then cadence. You pay for time that builds a repeatable rhythm, not just sessions.</p>
      <ul class="muted">
        <li>Outcome mapping and 1:1 coaching time</li>
        <li>Practical templates and daily cues</li>
        <li>Progress checkpoints and next-step transfer</li>
      </ul>
    </section>

    <section style="margin-top:22px" class="reveal">
      <h2 style="color:#e6fff6">Still deciding?</h2>
      <p class="muted">If you want to survey your options first, pick a short mapping call. That session surfaces the right scope so the investment matches what you want to create.</p>
      <a class="primary" href="book.html#map">Book a mapping call</a>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — Local practice in {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}" style="color:var(--muted)">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></div>
  </footer>

  <!-- Modal: Try it now -->
  <div id="modal" class="modalWrap" role="dialog" aria-modal="true">
    <div class="modal" aria-labelledby="modalTitle">
      <header>
        <div>
          <h3 id="modalTitle" style="margin:0;color:#012">Gentle practice</h3>
          <div class="muted">A short guided exercise to anchor attention</div>
        </div>
        <button class="closeBtn" id="closeModal">Close</button>
      </header>
      <div style="display:flex;gap:12px;margin-top:12px">
        <select id="exerciseSelect" style="flex:1;padding:8px;border-radius:8px;border:1px solid rgba(1,6,10,.08)">
          <option value="breath">Breathing rhythm — 2 minutes</option>
          <option value="journal">Mini-journal — 5 prompts</option>
          <option value="intent">Intention setting — 3 steps</option>
        </select>
        <button id="startBtn" class="btn">Start</button>
      </div>

      <div id="exercise" class="exercise" aria-live="polite"></div>
    </div>
  </div>

  <script>
    // Scroll reveal with prefers-reduced-motion
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduced){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));return}
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}},{threshold:0.12})
      );
      document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
    })();

    // Modal guided exercise
    (function(){
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('tryNow');
      const close = document.getElementById('closeModal');
      const startBtn = document.getElementById('startBtn');
      const select = document.getElementById('exerciseSelect');
      const box = document.getElementById('exercise');
      let timer=null, stepIndex=0, steps=[];

      function open(){modal.style.display='flex';box.innerHTML='';select.focus()}
      function closeModal(){modal.style.display='none';clearInterval(timer)}

      tryBtn.addEventListener('click',open);close.addEventListener('click',closeModal);
      modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});

      startBtn.addEventListener('click',()=>{
        const mode = select.value;box.innerHTML='';clearInterval(timer);
        if(mode==='breath'){
          steps = ['Find a comfortable seat.','Breathe in for 4 seconds…','Hold for 2 seconds…','Exhale for 6 seconds…','Repeat for two minutes.'];
          stepIndex=0;box.innerHTML='<div style="font-weight:700;color:#012">Breathing rhythm</div>';
          timer = setInterval(()=>{if(stepIndex<steps.length){box.innerHTML+='<div style="margin-top:10px">'+steps[stepIndex]+'</div>';stepIndex++} else {clearInterval(timer);box.innerHTML+='<div style="margin-top:10px;color:var(--muted)">Practice complete — take a breath before you move on.</div>'}},2000);
        } else if(mode==='journal'){
          steps = ['Name one thing going well today.','What felt draining?','One tiny change to try tomorrow.','Who could support that change?','One gratitude.'];
          stepIndex=0;box.innerHTML='<div style="font-weight:700;color:#012">Mini-journal</div>';
          timer = setInterval(()=>{if(stepIndex<steps.length){box.innerHTML+='<div style="margin-top:10px">• '+steps[stepIndex]+'</div>';stepIndex++} else {clearInterval(timer);box.innerHTML+='<div style="margin-top:10px;color:var(--muted)">Write freely — 2–5 minutes total.</div>'}},1800);
        } else if(mode==='intent'){
          steps = ['Center yourself — 20 seconds of stillness.','Name the one priority for today.','Identify the first tiny action.'];
          stepIndex=0;box.innerHTML='<div style="font-weight:700;color:#012">Intention setting</div>';
          timer = setInterval(()=>{if(stepIndex<steps.length){box.innerHTML+='<div style="margin-top:10px">'+(stepIndex+1)+'. '+steps[stepIndex]+'</div>';stepIndex++} else {clearInterval(timer);box.innerHTML+='<div class="muted" style="margin-top:10px">Carry this intention into your first task.</div>'}},2000);
        }
      });
    })();
  </script>
</body>
</html>"}
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stories — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Client stories and outcomes from coaching journeys." />
  <style>
    :root{--bg:#081118;--card:#07121a;--accent:#8ee7c8;--muted:#9fb7c3;--maxw:1040px}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e7f8f4;background:linear-gradient(180deg,#03131a 0%,#071728 100%)}
    header{max-width:var(--maxw);margin:20px auto;padding:16px;display:flex;align-items:center;justify-content:space-between}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6bd3ff);display:flex;align-items:center;justify-content:center;color:#052}
    nav a{color:#cfe9e0;text-decoration:none;margin:0 8px;font-weight:600}
    main{max-width:var(--maxw);margin:12px auto;padding:18px}
    h1{color:#e9fff6;margin:8px 0}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    .quote{font-style:italic;color:#dff7ef}
    .by{font-weight:700;color:var(--muted);margin-top:8px}
    .muted{color:var(--muted)}

    .ctaArea{margin-top:28px;padding:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);border-radius:12px;display:flex;justify-content:space-between;align-items:center}
    .primary{background:var(--accent);color:#022;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}

    .reveal{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s ease}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

    @media (max-width:920px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:800;color:#e6fff4">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Philosophy</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Paths</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <h1>Voices from the work</h1>
    <p class="muted">Real progress described in client words — focused on habits, clarity, and practical routine changes.</p>

    <section class="grid">
      <article class="card reveal">
        <div class="quote">"The mapping session made the noise fall away. I left with a one-page plan that actually fit into my week."</div>
        <div class="by">— Sara, product lead</div>
        <div class="muted" style="margin-top:8px">Outcome: A simple weekly review that reclaimed two hours of creative work per week.</div>
      </article>

      <article class="card reveal">
        <div class="quote">"We built three tiny cues that changed how I start my day. Small, immediate wins that stacked into a new rhythm."</div>
        <div class="by">— Omar, small business owner</div>
        <div class="muted" style="margin-top:8px">Outcome: Built habit loops to support a morning writing practice.</div>
      </article>

      <article class="card reveal">
        <div class="quote">"Coaching helped me translate stress into actions. Not therapy — practical steps I could test the next week."</div>
        <div class="by">— Nia, designer</div>
        <div class="muted" style="margin-top:8px">Outcome: A three-step nightly reset to improve sleep onset without medications.</div>
      </article>

      <article class="card reveal">
        <div class="quote">"The daily prompts kept me honest. In three months I could see how tiny shifts changed the shape of my month."</div>
        <div class="by">— Raj, engineer</div>
        <div class="muted" style="margin-top:8px">Outcome: Increased predictable focus blocks for deep work.</div>
      </article>

      <article class="card reveal">
        <div class="quote">"We designed a simple handoff to my partner that reduced weekend friction. Practical and fast."</div>
        <div class="by">— Lea, parent & consultant</div>
        <div class="muted" style="margin-top:8px">Outcome: Shared routines for household flow.</div>
      </article>

      <article class="card reveal">
        <div class="quote">"I expected pep talks. Instead I got frameworks, checklists, and a tiny system that actually stuck."</div>
        <div class="by">— Tom, startup founder</div>
        <div class="muted" style="margin-top:8px">Outcome: Improved meeting cadence and clearer priorities each week.</div>
      </article>
    </section>

    <section class="ctaArea reveal" style="margin-top:22px">
      <div>
        <div style="font-weight:800;color:#e6fff4">Ready to try a short practice?</div>
        <div class="muted">Open a guided exercise or reserve a short planning call to see what fits.</div>
      </div>
      <div style="display:flex;gap:10px;align-items:center">
        <button id="tryNow2" class="primary">Try a short exercise</button>
        <a class="primary" href="book.html">Reserve a planning call</a>
      </div>
    </section>

  </main>

  <footer style="max-width:var(--maxw);margin:28px auto 60px;padding:18px;color:var(--muted);text-align:center">{{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a> • <a href="tel:{{PHONE}}" style="color:var(--muted)">{{PHONE}}</a></footer>

  <!-- Modal component reused -->
  <div id="modal" style="display:none;position:fixed;inset:0;align-items:center;justify-content:center;background:rgba(0,0,0,0.6);z-index:60">
    <div style="background:#021220;color:#e8f7f2;width:92%;max-width:700px;border-radius:12px;padding:18px">
      <header style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <h3 style="margin:0;color:#012">Short guided practice</h3>
          <div class="muted">Choose a 2–5 minute anchor</div>
        </div>
        <button id="closeModal2" style="background:transparent;border:0;color:var(--muted);font-weight:700">Close</button>
      </header>
      <div style="margin-top:10px;display:flex;gap:8px">
        <select id="exerciseSelect2" style="flex:1;padding:8px;border-radius:8px;border:1px solid rgba(1,6,10,.08)">
          <option value="breath">Breathing — 2 minutes</option>
          <option value="journal">Mini journal — 3 prompts</option>
          <option value="intent">Intention — 3 steps</option>
        </select>
        <button id="startBtn2" style="background:var(--accent);border-radius:10px;padding:8px 12px;border:0;color:#012;font-weight:700">Start</button>
      </div>
      <div id="exercise2" style="margin-top:12px"></div>
    </div>
  </div>

  <script>
    // Reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));return}
      const obs = new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');obs.unobserve(en.target)}}),{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();

    // Modal logic
    (function(){
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('tryNow2');
      const close = document.getElementById('closeModal2');
      const start = document.getElementById('startBtn2');
      const select = document.getElementById('exerciseSelect2');
      const out = document.getElementById('exercise2');
      let t=null, idx=0, steps=[];
      function open(){modal.style.display='flex';select.focus();out.innerHTML=''}
      function closeModal(){modal.style.display='none';clearInterval(t)}
      tryBtn.addEventListener('click',open);close.addEventListener('click',closeModal);
      modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
      start.addEventListener('click',()=>{
        clearInterval(t);out.innerHTML='';idx=0;const v=select.value;
        if(v==='breath'){steps=['Sit tall.','Inhale 4s.','Hold 2s.','Exhale 6s.','Repeat.'];t=setInterval(()=>{if(idx<steps.length){out.innerHTML+='<div>'+steps[idx]+'</div>';idx++}else{clearInterval(t);out.innerHTML+='<div class="muted">Done.</div>'}},1800)}
        if(v==='journal'){steps=['One small win.','One tension to note.','One next step.'];t=setInterval(()=>{if(idx<steps.length){out.innerHTML+='<div>• '+steps[idx]+'</div>';idx++}else{clearInterval(t);out.innerHTML+='<div class="muted">Write for 3 minutes.</div>'}},1700)}
        if(v==='intent'){steps=['Name the focus.','Pick your first action.','Set a reminder.'];t=setInterval(()=>{if(idx<steps.length){out.innerHTML+='<div>'+steps[idx]+'</div>';idx++}else{clearInterval(t);out.innerHTML+='<div class="muted">Carry this into the next hour.</div>'}},1900)}
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Schedule a planning call or book a series — select your scope and we'll confirm next steps." />
  <style>
    :root{--bg:#071421;--card:#071020;--accent:#8ee7c8;--muted:#9fb8c3;--maxw:980px}
    body{margin:0;font-family:Inter,system-ui,Arial;color:#e6f7ef;background:linear-gradient(180deg,#021018 0%,#071421 100%)}
    header{max-width:var(--maxw);margin:18px auto;padding:14px;display:flex;justify-content:space-between;align-items:center}
    nav a{color:#cfe9e0;text-decoration:none;margin:0 8px;font-weight:600}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6bd3ff);display:flex;align-items:center;justify-content:center;color:#012}
    main{max-width:var(--maxw);margin:16px auto;padding:18px}

    .split{display:grid;grid-template-columns:1fr 380px;gap:20px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0;color:#e6fff4}
    .muted{color:var(--muted)}

    form{display:flex;flex-direction:column;gap:10px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#e7fff6}
    label{font-weight:700;color:#dfffe9}
    .small{font-size:13px;color:var(--muted)}
    .submit{background:var(--accent);color:#012;border:0;padding:12px 14px;border-radius:12px;font-weight:800}

    .options{display:flex;flex-direction:column;gap:8px}
    .option{padding:12px;border-radius:10px;background:rgba(255,255,255,0.01);display:flex;justify-content:space-between;align-items:center}

    .reveal{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s ease}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

    @media (max-width:920px){.split{grid-template-columns:1fr}}
  </style>
</head>
<body>
