        <select id="exerciseSelect3" style="flex:1;padding:8px;border-radius:8px;border:1px solid rgba(1,6,10,.08)">
          <option value="breath">Breath pause — 2m</option>
          <option value="intent">Set an intention — 3 steps</option>
        </select>
        <button id="startBtn3" style="background:var(--accent);border-radius:10px;padding:8px 12px;border:0;color:#012;font-weight:700">Start</button>
      </div>
      <div id="exercise3" style="margin-top:12px"></div>
    </div>
