  <script>
    // Reveal
    (function(){
      const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduce){document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));return}
      const observer = new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add('visible');observer.unobserve(en.target)}}),{threshold:0.1});
      document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
    })();

    // Form submit (mock)
    function handleSubmit(e){
      e.preventDefault();
      const status = document.getElementById('status');
      status.textContent = 'Sending request...';
      setTimeout(()=>{status.textContent = 'Request sent. We will follow up via email to confirm scheduling.'},900);
      return false;
    }

    // Modal practice logic
    (function(){
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('tryNow3');
      const close = document.getElementById('closeModal3');
      const start = document.getElementById('startBtn3');
      const select = document.getElementById('exerciseSelect3');
      const out = document.getElementById('exercise3');
      let t=null, idx=0, steps=[];
      function open(){modal.style.display='flex';select.focus();out.innerHTML=''}
      function closeModal(){modal.style.display='none';clearInterval(t)}
      tryBtn.addEventListener('click',open);close.addEventListener('click',closeModal);
      modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
      start.addEventListener('click',()=>{
        clearInterval(t);out.innerHTML='';idx=0;const v=select.value;
        if(v==='breath'){steps=['Sit comfortably.','Breathe in 4s.','Hold 2s.','Exhale 6s.','Repeat for two minutes.'];t=setInterval(()=>{if(idx<steps.length){out.innerHTML+='<div>'+steps[idx]+'</div>';idx++}else{clearInterval(t);out.innerHTML+='<div class="muted">Done.</div>'}},1700)}
        if(v==='intent'){steps=['Pause 15 seconds.','Name one focused outcome.','Choose the smallest next action.'];t=setInterval(()=>{if(idx<steps.length){out.innerHTML+='<div>'+steps[idx]+'</div>';idx++}else{clearInterval(t);out.innerHTML+='<div class="muted">Carry that forward.</div>'}},2000)}
      });
    })();
  </script>
